const fs = require("fs")
const path = require("path")

function diskStorage(options = {}) {
  return {
    destination: options.destination,
    filename: options.filename
  }
}

function parseContentDisposition(value) {
  const result = {}
  const parts = String(value || "").split(";").map((part) => part.trim())

  for (const part of parts) {
    const [key, rawValue] = part.split("=")
    if (!rawValue) {
      continue
    }

    const cleanValue = rawValue.replace(/^"|"$/g, "")
    result[key.toLowerCase()] = cleanValue
  }

  return result
}

function createMultipartParser(buffer, boundary) {
  const delimiter = Buffer.from(`--${boundary}`)
  const endDelimiter = Buffer.from(`--${boundary}--`)
  const parts = []
  let cursor = buffer.indexOf(delimiter)

  while (cursor !== -1) {
    cursor += delimiter.length
    if (buffer.slice(cursor, cursor + 2).toString() === "\r\n") {
      cursor += 2
    }

    const nextBoundaryIndex = buffer.indexOf(delimiter, cursor)
    const nextEndIndex = buffer.indexOf(endDelimiter, cursor)
    let partEnd = nextBoundaryIndex !== -1 ? nextBoundaryIndex : nextEndIndex

    if (partEnd === -1) {
      partEnd = buffer.length
    }

    let part = buffer.slice(cursor, partEnd)
    if (part.slice(-2).toString() === "\r\n") {
      part = part.slice(0, -2)
    }

    if (part.length > 0) {
      parts.push(part)
    }

    if (nextBoundaryIndex === -1) {
      break
    }

    cursor = nextBoundaryIndex
  }

  return parts
}

function multer(options = {}) {
  const storage = options.storage || {}
  const fileFilter = options.fileFilter
  const limits = options.limits || {}

  return {
    single(fieldName) {
      return function uploadMiddleware(req, res, next) {
        const contentType = String(req.headers["content-type"] || "")
        if (!contentType.includes("multipart/form-data")) {
          req.file = undefined
          req.body = req.body || {}
          next()
          return
        }

        const boundaryMatch = contentType.match(/boundary=([^;]+)/i)
        if (!boundaryMatch) {
          next(new Error("Boundary multipart inválido."))
          return
        }

        const boundary = boundaryMatch[1]
        const buffer = req.rawBody || Buffer.alloc(0)

        if (limits.fileSize && buffer.length > limits.fileSize * 2) {
          next(new Error("Arquivo muito grande."))
          return
        }

        req.body = req.body || {}
        const parts = createMultipartParser(buffer, boundary)
        let uploadedFile = null

        for (const part of parts) {
          const headerSeparator = part.indexOf(Buffer.from("\r\n\r\n"))
          if (headerSeparator === -1) {
            continue
          }

          const headerText = part.slice(0, headerSeparator).toString("utf8")
          const bodyBuffer = part.slice(headerSeparator + 4)
          const headerLines = headerText.split("\r\n").filter(Boolean)
          const headers = {}

          for (const line of headerLines) {
            const index = line.indexOf(":")
            if (index === -1) {
              continue
            }
            headers[line.slice(0, index).toLowerCase()] = line.slice(index + 1).trim()
          }

          const disposition = parseContentDisposition(headers["content-disposition"])
          const partName = disposition.name
          const filename = disposition.filename

          if (filename) {
            const mimetype = headers["content-type"] || "application/octet-stream"
            const file = {
              fieldname: partName,
              originalname: filename,
              mimetype,
              buffer: bodyBuffer,
              size: bodyBuffer.length
            }

            if (partName !== fieldName) {
              continue
            }

            if (typeof fileFilter === "function") {
              let accepted = false
              let filterError = null
              fileFilter(req, file, (error, allow) => {
                filterError = error || null
                accepted = allow !== false && !error
              })

              if (filterError) {
                next(filterError)
                return
              }

              if (!accepted) {
                next(new Error("Arquivo rejeitado pelo filtro."))
                return
              }
            }

            if (typeof storage.destination !== "function" || typeof storage.filename !== "function") {
              next(new Error("Storage não configurado."))
              return
            }

            storage.destination(req, file, (destinationError, destinationPath) => {
              if (destinationError) {
                next(destinationError)
                return
              }

              storage.filename(req, file, (filenameError, storedFilename) => {
                if (filenameError) {
                  next(filenameError)
                  return
                }

                const finalPath = path.join(destinationPath, storedFilename)
                fs.mkdirSync(destinationPath, { recursive: true })
                fs.writeFileSync(finalPath, bodyBuffer)

                uploadedFile = {
                  fieldname: fieldName,
                  originalname: filename,
                  encoding: "7bit",
                  mimetype,
                  destination: destinationPath,
                  filename: storedFilename,
                  path: finalPath,
                  size: bodyBuffer.length
                }
              })
            })
            continue
          }

          const value = bodyBuffer.toString("utf8")
          req.body[partName] = value
        }

        req.file = uploadedFile
        next()
      }
    }
  }
}

multer.diskStorage = diskStorage

module.exports = multer
